import manifest from '@/data/upscaled-images.json';
import { UPSCALED_BASE, hostedUrl } from './cardImage';

/**
 * Maps original EasyBroker photo URLs to AI-upscaled copies we host ourselves
 * (generated by scripts/upscale). Key = EasyBroker image id, the numeric segment in
 * https://assets.easybroker.com/property_images/<propertyNum>/<imageId>/EB-XXXX.jpeg
 * Falls back to the original URL when the base env var is unset or the image hasn't been
 * upscaled yet (e.g. brand-new listings), so nothing ever breaks.
 */
const MAP = manifest as Record<string, string>;
const ID_RE = /assets\.easybroker\.com\/property_images\/\d+\/(\d+)\//;

export function upscaledImageUrl(url: string): string {
    if (!UPSCALED_BASE || !url) return url;
    const m = url.match(ID_RE);
    const path = m ? MAP[m[1]] : undefined;
    return path ? hostedUrl(path) : url;
}
